package com.moishow.identity;

import org.springframework.beans.factory.ObjectProvider;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static com.moishow.identity.Models.*;
import static com.moishow.identity.FinanceModels.*;
import static com.moishow.identity.ApiProblem.require;

@Service @Profile("db")
class EventService {
 final Store db; final ClubService clubs; final ObjectProvider<FinanceService> finance;
 EventService(Store db,ClubService clubs,ObjectProvider<FinanceService> finance){this.db=db;this.clubs=clubs;this.finance=finance;}
 Object create(Actor actor,UUID clubId,IdentityController.EventForm b){var c=clubs.open(clubId);require(db.active(clubId,actor.userId()),403,"CLUB_MEMBER_REQUIRED");ClubService.expected(c,b.version());require(b.kind()!=null&&Set.of("REGULAR","LIGHTNING").contains(b.kind()),400,"INVALID_EVENT_KIND");if(b.kind().equals("REGULAR"))clubs.admin(actor,clubId);require(!b.publicEvent()||b.kind().equals("LIGHTNING"),400,"ONLY_LIGHTNING_CAN_BE_PUBLIC");require(b.startsAt()!=null&&b.endsAt()!=null&&b.endsAt().isAfter(b.startsAt())&&b.endsAt().isAfter(Instant.now()),400,"INVALID_EVENT_TIME");require(b.settlementMode()!=null&&Set.of("PREPAY","POSTPAY").contains(b.settlementMode()),400,"EXPLICIT_SETTLEMENT_MODE_REQUIRED");var e=new ClubEvent();e.clubId=clubId;e.hostId=actor.userId();e.responsibleId=actor.userId();e.settlementMode=b.settlementMode();e.title=ClubService.text(b.title(),100);e.kind=b.kind();e.publicEvent=b.publicEvent();e.startsAt=b.startsAt();e.endsAt=b.endsAt();db.save(e);c.version++;return eventView(e,actor);}
 ClubEvent lockEvent(UUID event){var e=db.find(ClubEvent.class,event);db.lock(Club.class,e.clubId);e=db.lock(ClubEvent.class,event);finance.getObject().lockExistingBook(event);return e;}
 Object round(Actor actor,UUID eventId,IdentityController.RoundForm b){var original=db.find(ClubEvent.class,eventId);clubs.open(original.clubId);var e=lockEvent(eventId);host(actor,e);ClubService.expected(e,b.version());require(b.capacity()!=null&&b.capacity()>=1&&b.capacity()<=10000&&b.closesAt()!=null&&!b.closesAt().isAfter(e.endsAt),400,"INVALID_ROUND");long fee=b.cancellationFee()==null?0:b.cancellationFee();require(fee>=0&&fee<=9007199254740991L,400,"INVALID_FEE");var book=finance.getObject().maybeBook(eventId);var revision=book!=null&&book.firstRegisteredAt!=null?finance.getObject().revision(actor,book,"실제 차수 추가"):null;var r=new EventRound();r.eventId=eventId;r.capacity=b.capacity();r.closesAt=b.closesAt();r.cancellationFee=fee;db.save(r);feeTerm(actor,r,"최초 고지");e.version++;if(book!=null){if(revision!=null)finance.getObject().finishRevision(book,revision);finance.getObject().result(book,book.id);}var response=new LinkedHashMap<String,Object>(roundView(r));response.put("eventVersion",e.version);return response;}
 void host(Actor actor,ClubEvent e){require(e.hostId.equals(actor.userId())&&db.active(e.clubId,actor.userId()),403,"EVENT_HOST_REQUIRED");}
 void financialHost(Actor a,ClubEvent e){require(e.responsibleId.equals(a.userId())||(e.hostId.equals(a.userId())&&db.active(e.clubId,a.userId())),403,"EVENT_FINANCIAL_HOST_REQUIRED");}
 boolean historical(UUID eventId,UUID user){return !db.list(Participation.class,"select p from Participation p, EventRound r where p.roundId=r.id and r.eventId=?1 and p.userId=?2 and p.everConfirmed=true",eventId,user).isEmpty();}
 boolean financial(Actor actor,ClubEvent e){return e.responsibleId.equals(actor.userId())||db.active(e.clubId,actor.userId())||historical(e.id,actor.userId())||finance.getObject().ownFinancialRelationship(e.id,actor.userId());}
 void visible(Actor actor,ClubEvent e){require(e.publicEvent||financial(actor,e),403,"EVENT_ACCESS_DENIED");}
 @Transactional(readOnly=true) public Object get(Actor actor,UUID id){var e=db.find(ClubEvent.class,id);visible(actor,e);return eventView(e,actor);}
 @Transactional(readOnly=true) public Object access(Actor actor,UUID id){var e=db.find(ClubEvent.class,id);visible(actor,e);return Map.of("viewSettlement",financial(actor,e),"manageSettlement",e.responsibleId.equals(actor.userId()),"manageEvent",e.hostId.equals(actor.userId())&&db.active(e.clubId,actor.userId()));}
 Map<String,Object> eventView(ClubEvent e,Actor actor){var v=new LinkedHashMap<String,Object>();v.put("id",e.id);v.put("clubId",e.clubId);v.put("title",e.title);v.put("kind",e.kind);v.put("publicEvent",e.publicEvent);v.put("settlementMode",e.settlementMode);v.put("scheduleVersion",e.scheduleVersion);v.put("startsAt",e.startsAt);v.put("endsAt",e.endsAt);v.put("version",e.version);v.put("rounds",db.list(EventRound.class,"from EventRound where eventId=?1 order by id",e.id).stream().map(this::roundView).toList());return v;} Map<String,Object> roundView(EventRound r){return Map.of("id",r.id,"eventId",r.eventId,"capacity",r.capacity,"closesAt",r.closesAt,"cancellationFee",r.cancellationFee,"feeVersion",r.feeVersion,"status",r.status,"version",r.version);}
 void feeTerm(Actor a,EventRound r,String reason){var term=new FeeTerm();term.roundId=r.id;term.termVersion=r.feeVersion;term.fee=r.cancellationFee;term.createdAt=Instant.now();term.createdBy=a.userId();term.reason=ClubService.text(reason,1000);db.save(term);}
 void consentRecord(Actor a,Participation p,String kind,long version,String decision,long fee){var c=new Consent();c.participationId=p.id;c.kind=kind;c.termVersion=version;c.decision=decision;c.fee=fee;c.createdAt=Instant.now();c.createdBy=a.userId();db.save(c);}
 Revision changeParticipant(Actor a,Participation p,String reason,Runnable mutation){return changeParticipant(a,p,reason,ignored->mutation.run());}
 Revision changeParticipant(Actor a,Participation p,String reason,java.util.function.Consumer<Revision> mutation){String oldStatus=p.status;long oldFee=p.agreedFee;var revision=finance.getObject().beforeParticipationChange(a,p,reason);mutation.accept(revision);p.version++;var round=db.find(EventRound.class,p.roundId);round.version++;var history=new ParticipationChange();history.eventId=round.eventId;history.participationId=p.id;history.revisionId=revision==null?null:revision.id;history.oldStatus=oldStatus;history.newStatus=p.status;history.oldFee=oldFee;history.newFee=p.agreedFee;history.feeVersion=p.agreedFeeVersion;history.waivedReason=p.waivedReason;history.reason=ClubService.text(reason,1000);history.createdAt=Instant.now();history.createdBy=a.userId();db.save(history);finance.getObject().onParticipantChanged(a,p,revision);return revision;}
 Object participate(Actor actor,UUID roundId,Long version){return participate(actor,roundId,version,null);}
 Object participate(Actor actor,UUID roundId,Long version,String memo){var initial=db.find(EventRound.class,roundId);var e=lockEvent(initial.eventId);boolean ended=!e.endsAt.isAfter(Instant.now());require(ended||db.find(Club.class,e.clubId).status.equals("ACTIVE"),409,"CLUB_NOT_ACTIVE");var r=db.lock(EventRound.class,roundId);ClubService.expected(r,version);require(!r.status.equals("CANCELLED"),409,"ROUND_CANCELLED");var m=db.member(e.clubId,actor.userId());require(m==null||!m.blacklisted,403,"CLUB_BLACKLISTED");require(e.publicEvent||db.active(e.clubId,actor.userId())||(ended&&m!=null&&Set.of("LEFT","EXPELLED").contains(m.status)),403,"EVENT_MEMBER_REQUIRED");require(db.one(Participation.class,"from Participation where roundId=?1 and userId=?2",roundId,actor.userId())==null,409,"PARTICIPATION_EXISTS");var p=new Participation();p.requestMemo=ClubService.optionalText(memo,1000);p.roundId=roundId;p.userId=actor.userId();p.agreedFee=r.cancellationFee;p.agreedFeeVersion=r.feeVersion;p.agreedAt=Instant.now();p.scheduleVersion=e.scheduleVersion;p.status=!ended&&r.closesAt.isAfter(Instant.now())?(hasSpace(r)?"CONFIRMED":"WAITLISTED"):"LATE_REQUESTED";p.everConfirmed=p.status.equals("CONFIRMED");db.save(p);if(p.status.equals("LATE_REQUESTED"))clubs.decision(actor,e.clubId,r.id,p.userId,"LATE_JOIN","SUBMITTED",p.requestMemo,"");consentRecord(actor,p,"FEE",r.feeVersion,"ACCEPTED",p.agreedFee);consentRecord(actor,p,"SCHEDULE",e.scheduleVersion,"ACCEPTED",p.agreedFee);r.version++;finance.getObject().onParticipantChanged(actor,p,null);return participantView(p,r);}
 Object changeParticipation(Actor a,UUID roundId,UUID participantId,String action,Long version){return changeParticipation(a,roundId,participantId,action,version,null);}
 Object changeParticipation(Actor a,UUID roundId,UUID participantId,String action,Long version,String reason){var initial=db.find(EventRound.class,roundId);var e=lockEvent(initial.eventId);var r=db.lock(EventRound.class,roundId);ClubService.expected(r,version);var p=db.find(Participation.class,participantId);require(p.roundId.equals(roundId),404,"NOT_FOUND");if(action.equals("approve")){boolean ended=!e.endsAt.isAfter(Instant.now());if(ended){financialHost(a,e);ClubService.text(reason,1000);}else host(a,e);require((ended||db.find(Club.class,e.clubId).status.equals("ACTIVE"))&&!r.status.equals("CANCELLED"),409,"EVENT_ENDED");var member=db.member(e.clubId,p.userId);require(member==null||!member.blacklisted,403,"CLUB_BLACKLISTED");require(e.publicEvent||db.active(e.clubId,p.userId)||(ended&&member!=null&&Set.of("LEFT","EXPELLED").contains(member.status)),403,"EVENT_MEMBER_REQUIRED");require(p.status.equals("LATE_REQUESTED")&&(ended||hasSpace(r)),409,"NOT_APPROVABLE");changeParticipant(a,p,ended?reason:"본인 합류 요청 승인",()->{p.status="CONFIRMED";p.everConfirmed=true;});clubs.decision(a,e.clubId,r.id,p.userId,"LATE_JOIN","APPROVED",p.requestMemo,reason==null?"":ClubService.optionalText(reason,1000));}
  else if(action.equals("reject")){host(a,e);require(p.status.equals("LATE_REQUESTED")&&!p.everConfirmed,409,"NOT_REJECTABLE");String why=ClubService.text(ClubService.optionalText(reason,1000),1000);p.status="REJECTED";p.version++;r.version++;clubs.decision(a,e.clubId,r.id,p.userId,"LATE_JOIN","REJECTED",p.requestMemo,why);}
  else if(action.equals("cancel")){require(p.userId.equals(a.userId()),403,"OWN_PARTICIPATION_ONLY");require(!Set.of("CANCELLED","REJECTED").contains(p.status),409,"PARTICIPATION_NOT_ACTIVE");var b=finance.getObject().maybeBook(e.id);if(b!=null&&b.firstRegisteredAt!=null)return finance.getObject().requestParticipationCorrection(a,p,reason==null?"등록 후 본인 취소 사실 검토 요청":reason);changeParticipant(a,p,reason==null?"참가자 본인 취소":reason,()->p.status="CANCELLED");}
  else if(action.equals("no-show")){financialHost(a,e);require(!e.startsAt.isAfter(Instant.now()),409,"EVENT_NOT_STARTED");require(p.status.equals("CONFIRMED"),409,"CONFIRMED_PARTICIPANT_REQUIRED");changeParticipant(a,p,ClubService.text(reason,1000),()->p.status="NO_SHOW");}
  else throw new ApiProblem(404,"UNKNOWN_OPERATION");return participantView(p,r);}
 Object changeFee(Actor a,UUID id,IdentityController.EventPolicyForm f){var initial=db.find(EventRound.class,id);var e=lockEvent(initial.eventId);financialHost(a,e);var r=db.lock(EventRound.class,id);ClubService.expected(r,f.version());require(!r.status.equals("CANCELLED"),409,"ROUND_CANCELLED");long fee=finance.getObject().money(f.cancellationFee(),false);String reason=ClubService.text(f.reason(),1000);r.cancellationFee=fee;r.feeVersion++;feeTerm(a,r,reason);for(var p:db.list(Participation.class,"from Participation where roundId=?1 and status<>'CANCELLED' and status<>'NO_SHOW' and status<>'REJECTED' order by id",id)){changeParticipant(a,p,reason,()->p.feeConsent="PENDING");consentRecord(a,p,"FEE",r.feeVersion,"PENDING",fee);}r.version++;return roundView(r);}
 Object consent(Actor a,UUID id,String kind,IdentityController.EventPolicyForm f){var initial=db.find(EventRound.class,id);var e=lockEvent(initial.eventId);var r=db.lock(EventRound.class,id);ClubService.expected(r,f.version());require(f.accepted()!=null,400,"EXPLICIT_CONSENT_REQUIRED");var p=db.one(Participation.class,"from Participation where roundId=?1 and userId=?2",id,a.userId());require(p!=null,404,"PARTICIPATION_NOT_FOUND");require(!Set.of("CANCELLED","NO_SHOW","REJECTED").contains(p.status),409,"PARTICIPATION_NOT_ACTIVE");boolean fee=kind.equals("fee");require(fee||kind.equals("schedule"),404,"UNKNOWN_CONSENT");require((fee?p.feeConsent:p.scheduleConsent).equals("PENDING"),409,"NO_PENDING_CONSENT");long term=fee?r.feeVersion:e.scheduleVersion;changeParticipant(a,p,f.accepted()?"변경 조건 본인 동의":"변경 조건 거부 무료 취소",()->{if(fee)p.feeConsent=f.accepted()?"ACCEPTED":"REJECTED";else p.scheduleConsent=f.accepted()?"ACCEPTED":"REJECTED";if(f.accepted()){if(fee){p.agreedFee=r.cancellationFee;p.agreedFeeVersion=r.feeVersion;p.agreedAt=Instant.now();}else p.scheduleVersion=e.scheduleVersion;}else{p.status="CANCELLED";p.agreedFee=0;p.waivedReason=fee?"FEE_CHANGE_DECLINED":"DATE_CHANGE_DECLINED";}});consentRecord(a,p,fee?"FEE":"SCHEDULE",term,f.accepted()?"ACCEPTED":"REJECTED",p.agreedFee);return participantView(p,r);}
 Object cancelRound(Actor a,UUID id,IdentityController.EventPolicyForm f){var initial=db.find(EventRound.class,id);var e=lockEvent(initial.eventId);financialHost(a,e);var r=db.lock(EventRound.class,id);ClubService.expected(r,f.version());require(!r.status.equals("CANCELLED"),409,"ROUND_ALREADY_CANCELLED");String reason=ClubService.text(f.reason(),1000);for(var p:db.list(Participation.class,"from Participation where roundId=?1 and status<>'REJECTED' order by id",id))changeParticipant(a,p,reason,()->{p.status="CANCELLED";p.agreedFee=0;p.waivedReason="HOST_CANCELLED";});r.status="CANCELLED";r.version++;var book=finance.getObject().maybeBook(e.id);if(book!=null)finance.getObject().result(book,book.id);return roundView(r);}
 Object schedule(Actor a,UUID id,IdentityController.EventPolicyForm f){var e=lockEvent(id);host(a,e);ClubService.expected(e,f.version());require(f.startsAt()!=null&&f.endsAt()!=null&&f.endsAt().isAfter(f.startsAt()),400,"INVALID_EVENT_TIME");var h=new ScheduleChange();h.eventId=id;h.termVersion=e.scheduleVersion+1;h.oldStartsAt=e.startsAt;h.oldEndsAt=e.endsAt;h.startsAt=f.startsAt();h.endsAt=f.endsAt();h.reason=ClubService.text(f.reason(),1000);h.createdAt=Instant.now();h.createdBy=a.userId();db.save(h);e.startsAt=f.startsAt();e.endsAt=f.endsAt();e.scheduleVersion++;e.version++;for(var p:db.list(Participation.class,"select p from Participation p, EventRound r where p.roundId=r.id and r.eventId=?1 and p.status not in ('CANCELLED','NO_SHOW','REJECTED') order by r.id,p.id",id)){changeParticipant(a,p,h.reason,()->p.scheduleConsent="PENDING");consentRecord(a,p,"SCHEDULE",e.scheduleVersion,"PENDING",p.agreedFee);}return eventView(e,a);}
 @Transactional(readOnly=true) public Object ownParticipation(Actor actor,UUID roundId){var r=db.find(EventRound.class,roundId);var p=db.one(Participation.class,"from Participation where roundId=?1 and userId=?2",roundId,actor.userId());require(p!=null,404,"PARTICIPATION_NOT_FOUND");var v=new LinkedHashMap<String,Object>(participantView(p,r));v.put("consentHistory",db.list(Consent.class,"from ParticipationConsent where participationId=?1 order by createdAt,id",p.id).stream().map(c->Map.of("kind",c.kind,"termVersion",c.termVersion,"decision",c.decision,"fee",c.fee,"createdAt",c.createdAt)).toList());return v;}
 @Transactional(readOnly=true) public Object participants(Actor actor,UUID eventId){var e=db.find(ClubEvent.class,eventId);require(e.responsibleId.equals(actor.userId())||(e.hostId.equals(actor.userId())&&db.active(e.clubId,actor.userId())),403,"EVENT_HOST_REQUIRED");return db.list(Participation.class,"select p from Participation p, EventRound r where p.roundId=r.id and r.eventId=?1 order by p.id",eventId).stream().map(p->{var v=new LinkedHashMap<String,Object>(participantView(p,db.find(EventRound.class,p.roundId)));var m=db.member(e.clubId,p.userId);boolean named=m!=null&&m.nickname!=null&&Set.of("ACTIVE","LEFT","EXPELLED").contains(m.status);v.put("nickname",named?m.nickname:db.find(Account.class,p.userId).nickname);v.put("departed",m!=null&&Set.of("LEFT","EXPELLED").contains(m.status));return v;}).toList();}
 @Transactional(readOnly=true) public Object requestHistory(Actor actor,UUID roundId){var round=db.find(EventRound.class,roundId);var event=db.find(ClubEvent.class,round.eventId);boolean manager=event.hostId.equals(actor.userId())&&db.active(event.clubId,actor.userId());return db.list(IdentityFollowupModels.Decision.class,"from RequestDecision where roundId=?1 and kind='LATE_JOIN' order by createdAt,id",roundId).stream().filter(d->manager||d.userId.equals(actor.userId())).map(clubs::decisionView).toList();}
 boolean hasSpace(EventRound r){return db.list(Participation.class,"from Participation where roundId=?1 and status='CONFIRMED'",r.id).size()<r.capacity;}
 Map<String,Object> participantView(Participation p,EventRound r){var v=new LinkedHashMap<String,Object>();v.put("id",p.id);v.put("roundId",p.roundId);v.put("userId",p.userId);v.put("status",p.status);v.put("agreedFee",p.agreedFee);v.put("agreedFeeVersion",p.agreedFeeVersion);v.put("agreedAt",p.agreedAt);v.put("feeConsent",p.feeConsent);v.put("scheduleConsent",p.scheduleConsent);v.put("scheduleVersion",p.scheduleVersion);v.put("waivedReason",p.waivedReason);v.put("version",r.version);return v;}
}
